package br.com.onda;
import java.nio.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LivePcmWindowTest {
 @Test public void downmixKeepsStereoAndWindowOverlapCorrect(){List<float[]> out=new ArrayList<>();List<Long> ends=new ArrayList<>();LivePcmWindow window=new LivePcmWindow(48000,2,(pcm,end)->{out.add(pcm);ends.add(end);});for(int sec=0;sec<14;sec++){ByteBuffer b=ByteBuffer.allocate(48000*4).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<48000;i++){short sample=(short)(Math.sin((sec*48000+i)*.01)*12000);b.putShort(sample).putShort(sample);}b.flip();window.accept(b);}assertEquals(2,out.size());assertEquals(Long.valueOf(128000),ends.get(0));assertEquals(Long.valueOf(224000),ends.get(1));assertEquals(128000,out.get(0).length);assertArrayEquals(Arrays.copyOfRange(out.get(0),96000,128000),Arrays.copyOf(out.get(1),32000),0);assertTrue(LivePcmWindow.audible(out.get(0)));}
 @Test public void partialBytesAndOppositeChannelsDoNotInventVoice(){List<float[]> out=new ArrayList<>();LivePcmWindow window=new LivePcmWindow(16000,2,(pcm,end)->out.add(pcm));byte[] frame={0,16,0,-16};for(int i=0;i<128000;i++){window.accept(ByteBuffer.wrap(frame,0,1));window.accept(ByteBuffer.wrap(frame,1,3));}assertEquals(1,out.size());for(float f:out.get(0))assertEquals(0,f,0);assertFalse(LivePcmWindow.audible(out.get(0)));}
 @Test public void musicMarkersAreNotTranslatedAsLyrics(){assertFalse(LiveRecognizer.recognizable("[Music]"));assertFalse(LiveRecognizer.recognizable("(soft music)"));assertFalse(LiveRecognizer.recognizable("…"));assertTrue(LiveRecognizer.recognizable("Twinkle little star"));assertTrue(LiveRecognizer.recognizable("中文歌曲内容"));}
 @Test public void capturedDecoderLoopIsNotPassedToTranslation(){String captured="Little star how I wonder what you "+"twinkle ".repeat(28);assertFalse(LiveRecognizer.recognizable(captured));assertTrue(LiveRecognizer.recognizable("Twinkle twinkle little star, how I wonder what you are"));assertTrue(LiveRecognizer.recognizable("Mary had a little lamb, little lamb, little lamb"));}
 @Test public void runawayPhraseIsRejectedWithoutSuppressingOrdinaryRefrains(){assertFalse(LiveRecognizer.recognizable("Thank you for watching. ".repeat(10)));assertTrue(LiveRecognizer.recognizable("Let it be, let it be, let it be, let it be"));}
}
